import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64
PTX_SOURCE = r"""
.version 7.8
.target sm_89
.address_size 64
.visible .entry conv2d_fwd(
    .param .u64 in_ptr,
    .param .u64 wt_ptr,
    .param .u64 bias_ptr,
    .param .u64 out_ptr,
    .param .u32 total_param
)
{
    .reg .pred %p<16>;
    .reg .f32  %f<54>;
    .reg .b32  %r<40>;
    .reg .b64  %rd<16>;
    // Register blocking: each thread computes 1 output pixel x 16 output
    // channels. CTA output tile is 16 (oh) x 16 (ow); staged input tile is
    // 71x72 floats (row padded to 72 words so the per-kh v4 tap prefetch
    // stays 16B aligned). Weights are now staged in three kh groups
    // (kh 0..3, 4..7, 8..10) of at most 44 taps instead of all 121 taps at
    // once, shrinking the weight region from 7744 B to 2816 B. Total shared
    // memory per CTA drops from 28192 B to 23264 B so 4 CTAs stay resident
    // per SM (was 3), lifting theoretical occupancy from 50% to 67%.
    // Shared layout: current weight group tap-major [<=44 taps][16 oc]
    // floats (2816 B) then input tile 71x72 (20448 B).
    .shared .align 16 .b8 smem_buf[23264];
    ld.param.u64 %rd1, [in_ptr];
    ld.param.u64 %rd2, [wt_ptr];
    ld.param.u64 %rd3, [bias_ptr];
    ld.param.u64 %rd4, [out_ptr];
    mov.u32 %r1, %ctaid.x;                  // output tile x (16 wide in ow)
    mov.u32 %r2, %ctaid.y;                  // output tile y (16 tall in oh)
    mov.u32 %r3, %ctaid.z;                  // batch index n
    mov.u32 %r4, %tid.x;                    // thread id 0..255
    shr.u32 %r5, %r4, 4;                    // local oh = tid / 16
    and.b32 %r6, %r4, 15;                   // local ow = tid % 16
    shl.b32 %r7, %r2, 4;
    add.u32 %r7, %r7, %r5;                  // global oh
    shl.b32 %r8, %r1, 4;
    add.u32 %r8, %r8, %r6;                  // global ow
    setp.lt.u32 %p1, %r7, 55;
    setp.lt.u32 %p2, %r8, 55;
    and.pred %p3, %p1, %p2;                 // pixel valid
    mov.u32 %r9, smem_buf;                  // shared memory base byte address
    // Per-thread input smem byte base: 2816 + (l_oh*4*72 + l_ow*4)*4
    mul.lo.u32 %r10, %r5, 1152;
    shl.b32 %r11, %r6, 4;
    add.u32 %r10, %r10, %r11;
    add.u32 %r10, %r10, %r9;
    add.u32 %r10, %r10, 2816;               // input region starts after weights
    shl.b32 %r12, %r2, 6;
    sub.s32 %r12, %r12, 2;                  // tile base h = ctaid.y*64 - pad
    shl.b32 %r13, %r1, 6;
    sub.s32 %r13, %r13, 2;                  // tile base w = ctaid.x*64 - pad
    mul.lo.u32 %r14, %r3, 3;                // n*3
    mul.lo.u32 %r15, %r3, 96;               // n*96
    mov.u32 %r16, 0;                        // oc chunk index (6 chunks of 16)
CHUNK_LOOP:
    setp.ge.u32 %p4, %r16, 6;
    @%p4 bra CHUNK_DONE;
    shl.b32 %r17, %r16, 4;                  // oc_base = chunk*16
    mov.f32 %f10, 0f00000000;
    mov.f32 %f11, 0f00000000;
    mov.f32 %f12, 0f00000000;
    mov.f32 %f13, 0f00000000;
    mov.f32 %f14, 0f00000000;
    mov.f32 %f15, 0f00000000;
    mov.f32 %f16, 0f00000000;
    mov.f32 %f17, 0f00000000;
    mov.f32 %f18, 0f00000000;
    mov.f32 %f19, 0f00000000;
    mov.f32 %f20, 0f00000000;
    mov.f32 %f21, 0f00000000;
    mov.f32 %f22, 0f00000000;
    mov.f32 %f23, 0f00000000;
    mov.f32 %f24, 0f00000000;
    mov.f32 %f25, 0f00000000;
    mov.u32 %r18, 0;                        // ic
IC_LOOP:
    setp.ge.u32 %p5, %r18, 3;
    @%p5 bra IC_DONE;
    // ---- Stage input tile (71x71) for channel ic via cp.async ----
    // Async 4B global->shared copies bypass the register file and remove
    // ld->st dependency stalls; out-of-range taps are zero-filled by
    // passing src_size = 0 (no global bytes read). Row/col are advanced
    // incrementally: idx += 256 <=> row += 3, col += 43, carry at 71.
    add.u32 %r19, %r14, %r18;
    mul.lo.u32 %r19, %r19, 50176;           // channel plane element offset
    mov.u32 %r20, %r4;                      // idx
    div.u32 %r21, %r20, 71;                 // row
    mul.lo.u32 %r22, %r21, 71;
    sub.u32 %r22, %r20, %r22;               // col
STG_IN_LOOP:
    setp.ge.u32 %p6, %r20, 5041;
    @%p6 bra STG_IN_DONE;
    add.s32 %r23, %r12, %r21;               // h
    add.s32 %r24, %r13, %r22;               // w
    setp.lt.s32 %p7, %r23, 0;
    setp.ge.s32 %p8, %r23, 224;
    or.pred %p9, %p7, %p8;
    setp.lt.s32 %p10, %r24, 0;
    setp.ge.s32 %p11, %r24, 224;
    or.pred %p12, %p9, %p10;
    or.pred %p12, %p12, %p11;               // out of range
    mul.lo.u32 %r25, %r23, 224;
    add.s32 %r25, %r25, %r24;
    add.u32 %r25, %r25, %r19;
    mul.wide.u32 %rd5, %r25, 4;
    add.u64 %rd6, %rd1, %rd5;
    @%p12 mov.u64 %rd6, %rd1;               // clamp OOB src (not read)
    selp.b32 %r25, 0, 4, %p12;              // src_size 0 -> zero fill
    mul.lo.u32 %r26, %r21, 72;              // padded row stride (words)
    add.u32 %r26, %r26, %r22;
    shl.b32 %r26, %r26, 2;
    add.u32 %r26, %r26, %r9;
    add.u32 %r26, %r26, 2816;
    cp.async.ca.shared.global [%r26], [%rd6], 4, %r25;
    add.u32 %r20, %r20, 256;
    add.u32 %r22, %r22, 43;
    setp.ge.u32 %p7, %r22, 71;
    @%p7 sub.u32 %r22, %r22, 71;
    @%p7 add.u32 %r21, %r21, 4;
    @!%p7 add.u32 %r21, %r21, 3;
    bra STG_IN_LOOP;
STG_IN_DONE:
    // ---- Stage weight group 0 (taps 0..43 = kh 0..3) transposed ----
    // The weight region now holds only one kh group (<=44 taps) at a time;
    // groups 1 and 2 are restaged inside the kh loop (WT_RESTAGE_G1/G2).
    // idx += 256  <=>  j += 5, tap += 36, with carry when tap >= 44.
    mov.u32 %r27, %r4;                      // idx
    div.u32 %r28, %r27, 44;                 // j (local oc)
    mul.lo.u32 %r29, %r28, 44;
    sub.u32 %r30, %r27, %r29;               // local tap (0..43)
STG_WT_G0_LOOP:
    setp.ge.u32 %p13, %r27, 704;
    @%p13 bra STG_WT_G0_DONE;
    add.u32 %r31, %r17, %r28;               // oc
    mul.lo.u32 %r31, %r31, 3;
    add.u32 %r31, %r31, %r18;
    mul.lo.u32 %r31, %r31, 121;
    add.u32 %r31, %r31, %r30;               // global tap == local tap
    mul.wide.u32 %rd7, %r31, 4;
    add.u64 %rd8, %rd2, %rd7;
    shl.b32 %r32, %r30, 6;                  // tap*64 bytes
    shl.b32 %r36, %r28, 2;                  // j*4 bytes
    add.u32 %r32, %r32, %r36;
    add.u32 %r32, %r32, %r9;
    cp.async.ca.shared.global [%r32], [%rd8], 4;
    add.u32 %r27, %r27, 256;
    add.u32 %r30, %r30, 36;
    setp.ge.u32 %p15, %r30, 44;
    @%p15 sub.u32 %r30, %r30, 44;
    @%p15 add.u32 %r28, %r28, 6;
    @!%p15 add.u32 %r28, %r28, 5;
    bra STG_WT_G0_LOOP;
STG_WT_G0_DONE:
    cp.async.commit_group;
    cp.async.wait_group 0;
    bar.sync 0;
    mov.u32 %r34, %r9;                      // weight smem base (tap-major)
    mov.u32 %r33, %r10;                     // input smem row cursor (pixel 0)
    mov.u32 %r35, 0;                        // kh
KH_LOOP:
    setp.ge.u32 %p14, %r35, 11;
    @%p14 bra KH_DONE;
    @!%p3 bra KH_BODY_SKIP;
    // Prefetch this kh row's input taps with aligned ld.shared.v4 (12 words
    // cover kw 0..10); consume from registers.
    ld.shared.v4.f32 {%f42,%f43,%f44,%f45}, [%r33];
    ld.shared.v4.f32 {%f46,%f47,%f48,%f49}, [%r33+16];
    ld.shared.v4.f32 {%f50,%f51,%f52,%f53}, [%r33+32];
    // kw = 0
    ld.shared.v4.f32 {%f3,%f4,%f5,%f6}, [%r34];
    fma.rn.f32 %f10, %f42, %f3, %f10;
    fma.rn.f32 %f11, %f42, %f4, %f11;
    fma.rn.f32 %f12, %f42, %f5, %f12;
    fma.rn.f32 %f13, %f42, %f6, %f13;
    ld.shared.v4.f32 {%f3,%f4,%f5,%f6}, [%r34+16];
    fma.rn.f32 %f14, %f42, %f3, %f14;
    fma.rn.f32 %f15, %f42, %f4, %f15;
    fma.rn.f32 %f16, %f42, %f5, %f16;
    fma.rn.f32 %f17, %f42, %f6, %f17;
    ld.shared.v4.f32 {%f3,%f4,%f5,%f6}, [%r34+32];
    fma.rn.f32 %f18, %f42, %f3, %f18;
    fma.rn.f32 %f19, %f42, %f4, %f19;
    fma.rn.f32 %f20, %f42, %f5, %f20;
    fma.rn.f32 %f21, %f42, %f6, %f21;
    ld.shared.v4.f32 {%f3,%f4,%f5,%f6}, [%r34+48];
    fma.rn.f32 %f22, %f42, %f3, %f22;
    fma.rn.f32 %f23, %f42, %f4, %f23;
    fma.rn.f32 %f24, %f42, %f5, %f24;
    fma.rn.f32 %f25, %f42, %f6, %f25;
    // kw = 1
    ld.shared.v4.f32 {%f3,%f4,%f5,%f6}, [%r34+64];
    fma.rn.f32 %f10, %f43, %f3, %f10;
    fma.rn.f32 %f11, %f43, %f4, %f11;
    fma.rn.f32 %f12, %f43, %f5, %f12;
    fma.rn.f32 %f13, %f43, %f6, %f13;
    ld.shared.v4.f32 {%f3,%f4,%f5,%f6}, [%r34+80];
    fma.rn.f32 %f14, %f43, %f3, %f14;
    fma.rn.f32 %f15, %f43, %f4, %f15;
    fma.rn.f32 %f16, %f43, %f5, %f16;
    fma.rn.f32 %f17, %f43, %f6, %f17;
    ld.shared.v4.f32 {%f3,%f4,%f5,%f6}, [%r34+96];
    fma.rn.f32 %f18, %f43, %f3, %f18;
    fma.rn.f32 %f19, %f43, %f4, %f19;
    fma.rn.f32 %f20, %f43, %f5, %f20;
    fma.rn.f32 %f21, %f43, %f6, %f21;
    ld.shared.v4.f32 {%f3,%f4,%f5,%f6}, [%r34+112];
    fma.rn.f32 %f22, %f43, %f3, %f22;
    fma.rn.f32 %f23, %f43, %f4, %f23;
    fma.rn.f32 %f24, %f43, %f5, %f24;
    fma.rn.f32 %f25, %f43, %f6, %f25;
    // kw = 2
    ld.shared.v4.f32 {%f3,%f4,%f5,%f6}, [%r34+128];
    fma.rn.f32 %f10, %f44, %f3, %f10;
    fma.rn.f32 %f11, %f44, %f4, %f11;
    fma.rn.f32 %f12, %f44, %f5, %f12;
    fma.rn.f32 %f13, %f44, %f6, %f13;
    ld.shared.v4.f32 {%f3,%f4,%f5,%f6}, [%r34+144];
    fma.rn.f32 %f14, %f44, %f3, %f14;
    fma.rn.f32 %f15, %f44, %f4, %f15;
    fma.rn.f32 %f16, %f44, %f5, %f16;
    fma.rn.f32 %f17, %f44, %f6, %f17;
    ld.shared.v4.f32 {%f3,%f4,%f5,%f6}, [%r34+160];
    fma.rn.f32 %f18, %f44, %f3, %f18;
    fma.rn.f32 %f19, %f44, %f4, %f19;
    fma.rn.f32 %f20, %f44, %f5, %f20;
    fma.rn.f32 %f21, %f44, %f6, %f21;
    ld.shared.v4.f32 {%f3,%f4,%f5,%f6}, [%r34+176];
    fma.rn.f32 %f22, %f44, %f3, %f22;
    fma.rn.f32 %f23, %f44, %f4, %f23;
    fma.rn.f32 %f24, %f44, %f5, %f24;
    fma.rn.f32 %f25, %f44, %f6, %f25;
    // kw = 3
    ld.shared.v4.f32 {%f3,%f4,%f5,%f6}, [%r34+192];
    fma.rn.f32 %f10, %f45, %f3, %f10;
    fma.rn.f32 %f11, %f45, %f4, %f11;
    fma.rn.f32 %f12, %f45, %f5, %f12;
    fma.rn.f32 %f13, %f45, %f6, %f13;
    ld.shared.v4.f32 {%f3,%f4,%f5,%f6}, [%r34+208];
    fma.rn.f32 %f14, %f45, %f3, %f14;
    fma.rn.f32 %f15, %f45, %f4, %f15;
    fma.rn.f32 %f16, %f45, %f5, %f16;
    fma.rn.f32 %f17, %f45, %f6, %f17;
    ld.shared.v4.f32 {%f3,%f4,%f5,%f6}, [%r34+224];
    fma.rn.f32 %f18, %f45, %f3, %f18;
    fma.rn.f32 %f19, %f45, %f4, %f19;
    fma.rn.f32 %f20, %f45, %f5, %f20;
    fma.rn.f32 %f21, %f45, %f6, %f21;
    ld.shared.v4.f32 {%f3,%f4,%f5,%f6}, [%r34+240];
    fma.rn.f32 %f22, %f45, %f3, %f22;
    fma.rn.f32 %f23, %f45, %f4, %f23;
    fma.rn.f32 %f24, %f45, %f5, %f24;
    fma.rn.f32 %f25, %f45, %f6, %f25;
    // kw = 4
    ld.shared.v4.f32 {%f3,%f4,%f5,%f6}, [%r34+256];
    fma.rn.f32 %f10, %f46, %f3, %f10;
    fma.rn.f32 %f11, %f46, %f4, %f11;
    fma.rn.f32 %f12, %f46, %f5, %f12;
    fma.rn.f32 %f13, %f46, %f6, %f13;
    ld.shared.v4.f32 {%f3,%f4,%f5,%f6}, [%r34+272];
    fma.rn.f32 %f14, %f46, %f3, %f14;
    fma.rn.f32 %f15, %f46, %f4, %f15;
    fma.rn.f32 %f16, %f46, %f5, %f16;
    fma.rn.f32 %f17, %f46, %f6, %f17;
    ld.shared.v4.f32 {%f3,%f4,%f5,%f6}, [%r34+288];
    fma.rn.f32 %f18, %f46, %f3, %f18;
    fma.rn.f32 %f19, %f46, %f4, %f19;
    fma.rn.f32 %f20, %f46, %f5, %f20;
    fma.rn.f32 %f21, %f46, %f6, %f21;
    ld.shared.v4.f32 {%f3,%f4,%f5,%f6}, [%r34+304];
    fma.rn.f32 %f22, %f46, %f3, %f22;
    fma.rn.f32 %f23, %f46, %f4, %f23;
    fma.rn.f32 %f24, %f46, %f5, %f24;
    fma.rn.f32 %f25, %f46, %f6, %f25;
    // kw = 5
    ld.shared.v4.f32 {%f3,%f4,%f5,%f6}, [%r34+320];
    fma.rn.f32 %f10, %f47, %f3, %f10;
    fma.rn.f32 %f11, %f47, %f4, %f11;
    fma.rn.f32 %f12, %f47, %f5, %f12;
    fma.rn.f32 %f13, %f47, %f6, %f13;
    ld.shared.v4.f32 {%f3,%f4,%f5,%f6}, [%r34+336];
    fma.rn.f32 %f14, %f47, %f3, %f14;
    fma.rn.f32 %f15, %f47, %f4, %f15;
    fma.rn.f32 %f16, %f47, %f5, %f16;
    fma.rn.f32 %f17, %f47, %f6, %f17;
    ld.shared.v4.f32 {%f3,%f4,%f5,%f6}, [%r34+352];
    fma.rn.f32 %f18, %f47, %f3, %f18;
    fma.rn.f32 %f19, %f47, %f4, %f19;
    fma.rn.f32 %f20, %f47, %f5, %f20;
    fma.rn.f32 %f21, %f47, %f6, %f21;
    ld.shared.v4.f32 {%f3,%f4,%f5,%f6}, [%r34+368];
    fma.rn.f32 %f22, %f47, %f3, %f22;
    fma.rn.f32 %f23, %f47, %f4, %f23;
    fma.rn.f32 %f24, %f47, %f5, %f24;
    fma.rn.f32 %f25, %f47, %f6, %f25;
    // kw = 6
    ld.shared.v4.f32 {%f3,%f4,%f5,%f6}, [%r34+384];
    fma.rn.f32 %f10, %f48, %f3, %f10;
    fma.rn.f32 %f11, %f48, %f4, %f11;
