    fma.rn.f32 %f10, %f49, %f3, %f10;
    fma.rn.f32 %f11, %f49, %f4, %f11;
    fma.rn.f32 %f12, %f49, %f5, %f12;
    fma.rn.f32 %f13, %f49, %f6, %f13;
    ld.shared.v4.f32 {%f3,%f4,%f5,%f6}, [%r34+464];
    fma.rn.f32 %f14, %f49, %f3, %f14;
    fma.rn.f32 %f15, %f49, %f4, %f15;
    fma.rn.f32 %f16, %f49, %f5, %f16;
