    // kw = 8
    ld.shared.v4.f32 {%f3,%f4,%f5,%f6}, [%r34+512];
    fma.rn.f32 %f10, %f50, %f3, %f10;
    fma.rn.f32 %f11, %f50, %f4, %f11;
