    ld.shared.v4.f32 {%f3,%f4,%f5,%f6}, [%r34+544];
    fma.rn.f32 %f18, %f50, %f3, %f18;
    fma.rn.f32 %f19, %f50, %f4, %f19;
    fma.rn.f32 %f20, %f50, %f5, %f20;
